// Generated by `pnpm nx g @app/generators:action messages.publish-history.get`. Requests go through the real router
// with createTestEngine().inject. They fail until createMessagesPublishHistoryGetAction is implemented; do not weaken them.
import { messagesPublishHistoryGet } from '@app/contracts';
import {
  createLogger,
  createManualClock,
  createRoleAuthorizer,
} from '@app/kernel';
import {
  createFakeSealer,
  createMemoryPublishHistory,
  createMessagesFakeDeps,
  createMessagesPublishHistoryGetAction,
  createPublishHistory,
  type PublishRecord,
} from '@app/svc-messages';
import { afterEach, describe, expect, it } from 'vitest';

import { createTestEngine, type TestEngine } from '../create-test-engine.ts';

const subject = () =>
  createMessagesPublishHistoryGetAction(createMessagesFakeDeps());
const def = messagesPublishHistoryGet;
const record = (ownerId: string, over: Partial<PublishRecord> = {}) => ({
  ownerId,
  connectionId: 'c1',
  vhost: '/',
  at: 1_700_000_000_000,
  exchange: '',
  routingKey: 'orders',
  copies: 1,
  summary: {
    confirmed: 1,
    nacked: 0,
    returned: 0,
    blocked: 0,
    timeout: 0,
    failed: 0,
    'not-sent': 0,
  },
  props: { contentType: 'text/plain' },
  body: new TextEncoder().encode('hello'),
  ...over,
});

/** A history store over the fakes of the module; the spec records into it as the engine's principal. */
function createStore() {
  let n = 0;
  return createPublishHistory({
    history: createMemoryPublishHistory(),
    sealer: createFakeSealer(),
    newId: () => {
      n += 1;
      return `entry-${String(n)}`;
    },
    clock: createManualClock(1_700_000_000_000),
    logger: createLogger({ level: 'silent' }),
  });
}

let engine: TestEngine;

afterEach(async () => {
  await engine.close();
});

describe('GET /connections/{cid}/messages/publish-history/{entryId}', () => {
  it('route 1: the route runs messages.publish-history.get and answers in the shape of the contract', async () => {
    const store = createStore();
    engine = createTestEngine({
      actions: [createMessagesPublishHistoryGetAction({ store })],
    });
    const id = await store.record(
      record(engine.principal.id, {
        headers: {
          authorization: { t: 'string', v: 'Bearer HTTP-SPEC-SECRET-1' },
        },
      }),
    );

    const answer = await engine.inject({
      method: 'GET',
      path: `/connections/c1/messages/publish-history/${id}`,
    });

    expect(answer.statusCode).toBe(200);
    expect(def.output.safeParse(answer.json()).success).toBe(true);
    expect(answer.json()).toMatchObject({
      entry: { id, routingKey: 'orders' },
      resend: { masked: ['header:authorization'] },
    });
    expect(answer.body).not.toContain('HTTP-SPEC-SECRET-1');
    // A read leaves no audit row.
    expect(engine.audit.attempts).toEqual([]);
  });

  it('route 1b: an entry of another owner, another connection or no one is a 404 Problem', async () => {
    const store = createStore();
    engine = createTestEngine({
      actions: [createMessagesPublishHistoryGetAction({ store })],
    });
    const theirs = await store.record(record('someone-else'));
    const mine = await store.record(record(engine.principal.id));
    const get = (cid: string, id: string) =>
      engine.inject({
        method: 'GET',
        path: `/connections/${cid}/messages/publish-history/${id}`,
      });

    const answers = [
      await get('c1', theirs),
      await get('c2', mine),
      await get('c1', 'no-such-entry'),
    ];

    expect(answers.map((answer) => answer.statusCode)).toEqual([404, 404, 404]);
    expect(answers[0]?.json()).toMatchObject({ code: 'NOT_FOUND' });
  });

  it('route 2: a request without the launch token is refused and nothing runs', async () => {
    engine = createTestEngine({ actions: [subject()] });

    const answer = await engine.inject({
      method: 'GET',
      path: '/connections/c1/messages/publish-history/sample',
      authenticated: false,
    });

    expect(answer.statusCode).toBe(401);
    expect(engine.audit.attempts).toEqual([]);
  });

  it('route 3: a caller that does not hold messages.publish gets 403 and nothing runs', async () => {
    engine = createTestEngine({
      actions: [subject()],
      authorizer: createRoleAuthorizer({}),
    });
    const answer = await engine.inject({
      method: 'GET',
      path: '/connections/c1/messages/publish-history/sample',
    });

    expect(answer.statusCode).toBe(403);
    expect(answer.json()).toMatchObject({ code: 'FORBIDDEN_RBAC' });
    expect(engine.audit.attempts).toEqual([]);
    expect(engine.writeCalls).toEqual([]);
  });

  it('route 4: input that breaks the contract is a 400 Problem and nothing runs', async () => {
    engine = createTestEngine({ actions: [subject()] });
    const answer = await engine.inject({
      method: 'GET',
      path: '/connections/c1/messages/publish-history/sample?unexpected=1',
    });

    expect(answer.statusCode).toBe(400);
    expect(answer.json()).toMatchObject({ code: 'VALIDATION_FAILED' });
    expect(engine.audit.attempts).toEqual([]);
  });

  it('route 5: another method on the same path is 405', async () => {
    engine = createTestEngine({ actions: [subject()] });

    const answer = await engine.inject({
      method: 'DELETE',
      path: '/connections/c1/messages/publish-history/sample',
    });

    expect(answer.statusCode).toBe(405);
    expect(answer.headers.allow).toBe('GET');
  });
});
